"use client";

import type { ArtPair } from "@/lib/content/sections";
import { StoryCarousel } from "./StoryCarousel";

interface EditorialSlide {
  id: string;
  art: ArtPair;
  eyebrow?: string;
  title: string;
  body: string;
  ctaLabel: string;
  ctaHref: string;
  // Layout options from the earlier full-bleed design. Still stored in the
  // admin's data, so they stay in the type; the split layout does not need them.
  buttonVariant: "primary" | "secondary";
  textAlign: "left" | "right" | "center";
  verticalAlign?: "bottom" | "center";
  ink?: "dark";
}

/**
 * The editorial edits (womenswear, stoles): an arch-framed photograph on the
 * ivory fold, with the words beside it.
 */
export function EditorialSlideshow({ slides }: { slides: EditorialSlide[] }) {
  return <StoryCarousel slides={slides} label="Editorial collections" ground="ivory" frame="arch" imageSide="right" />;
}
