"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import Link from "next/link";
import Image from "next/image";

import { toneFor } from "../Frame";
import { BRAND } from "@/lib/brand";
import type { HeroSlide } from "@/lib/content/sections";
import { ImageLink } from "../ImageLink";

const INTERVAL_MS = 6500;

/**
 * The hero (redesign, 1 Oct 2026).
 *
 * Slides are stacked and cross-dissolve rather than sliding past one another;
 * the photograph on screen drifts very slowly larger while it is shown, the
 * way a length of silk moves when it is held up to the light. The caption sits
 * low on the left in the display face. Along the foot runs a row of numbered
 * chapters, each with a gold thread that fills while its slide plays, which
 * doubles as the control: click a chapter to go to it.
 *
 * It pauses on hover and on keyboard focus, has a pause button of its own, and
 * never advances for reduced-motion users. Every slide's words, photograph and
 * link come from the admin.
 */
export function HeroCarousel({
  slides,
  isPageTitle = true,
}: {
  slides: HeroSlide[];
  isPageTitle?: boolean;
}) {
  const [active, setActive] = useState(0);
  const [paused, setPaused] = useState(false);
  const [userPaused, setUserPaused] = useState(false);
  const [reduced, setReduced] = useState(false);
  const rootRef = useRef<HTMLElement>(null);
  const count = slides.length;

  useEffect(() => {
    const query = window.matchMedia("(prefers-reduced-motion: reduce)");
    const sync = () => setReduced(query.matches);
    sync();
    query.addEventListener("change", sync);
    return () => query.removeEventListener("change", sync);
  }, []);

  const go = useCallback((index: number) => setActive(((index % count) + count) % count), [count]);

  const running = !paused && !userPaused && !reduced && count > 1;

  useEffect(() => {
    if (!running) return;
    const timer = setTimeout(() => go(active + 1), INTERVAL_MS);
    return () => clearTimeout(timer);
  }, [running, active, go]);

  if (count === 0) return null;

  return (
    <section
      ref={rootRef}
      className="relative h-[calc(100svh-100px)] max-h-[960px] min-h-[560px] w-full overflow-hidden bg-night"
      aria-label="Featured collections"
      aria-roledescription="carousel"
      onMouseEnter={() => setPaused(true)}
      onMouseLeave={() => setPaused(false)}
      onFocus={() => setPaused(true)}
      onBlur={(event) => {
        if (!rootRef.current?.contains(event.relatedTarget as Node)) setPaused(false);
      }}
      onKeyDown={(event) => {
        if (event.key === "ArrowRight") go(active + 1);
        if (event.key === "ArrowLeft") go(active - 1);
      }}
    >
      {/* The page's h1, for screen readers: the design leads with a photograph. */}
      {isPageTitle ? <h1 className="sr-only">{BRAND.name}: handwoven Banarasi textiles</h1> : null}

      {slides.map((slide, index) => {
        const isActive = index === active;
        const dark = slide.ink === "dark";
        return (
          <div
            key={slide.id}
            role="group"
            aria-roledescription="slide"
            aria-label={`${index + 1} of ${count}: ${slide.title}`}
            aria-hidden={!isActive}
            className={`absolute inset-0 transition-opacity duration-[1400ms] ease-[var(--ease-out)] ${
              isActive ? "z-10 opacity-100" : "pointer-events-none z-0 opacity-0"
            }`}
          >
            <div className="absolute inset-0" style={{ backgroundColor: toneFor(slide.art.desktop.tone) }}>
              {slide.art.desktop.src ? (
                <Image
                  src={slide.art.desktop.src}
                  alt={slide.title}
                  fill
                  sizes="100vw"
                  loading={index === 0 ? "eager" : "lazy"}
                  fetchPriority={index === 0 ? "high" : "auto"}
                  className={`object-cover object-center transition-transform ease-linear ${
                    isActive && !reduced ? "scale-[1.07] duration-[9000ms]" : "scale-100 duration-[1400ms]"
                  }`}
                />
              ) : null}
            </div>

            <ImageLink href={slide.ctaHref} duplicate className="absolute inset-0" />

            {!dark && (
              <div
                aria-hidden
                className="pointer-events-none absolute inset-0 bg-[linear-gradient(to_top,rgb(23_19_31/0.78),rgb(23_19_31/0.18)_45%,transparent_70%),linear-gradient(to_right,rgb(23_19_31/0.35),transparent_55%)]"
              />
            )}

            <div className={`pointer-events-none absolute inset-0 flex items-end pb-36 md:pb-40 ${dark ? "caption-dark" : ""}`}>
              <div className="wrap-wide">
                <div className="max-w-[560px]">
                  {slide.eyebrow ? (
                    <p
                      className={`flex items-center gap-3 font-ui text-[11px] font-medium uppercase tracking-[0.28em] ${dark ? "text-accent" : "text-gold-soft"} ${
                        isActive ? "animate-[riseIn_900ms_var(--ease-out)_both]" : ""
                      }`}
                    >
                      <span className="h-px w-8 bg-current" aria-hidden="true" />
                      {slide.eyebrow}
                    </p>
                  ) : null}
                  <h2
                    className={`mt-5 font-display text-[clamp(2.75rem,1.6rem+4.4vw,5.5rem)] leading-[0.98] tracking-[0.01em] ${dark ? "text-ink" : "text-paper"} ${
                      isActive ? "animate-[riseIn_1000ms_var(--ease-out)_120ms_both]" : ""
                    }`}
                  >
                    {slide.title}
                  </h2>
                  <p
                    className={`mt-5 max-w-[42ch] font-serif text-[18px] leading-[1.55] md:text-[20px] ${dark ? "text-ink-body" : "text-paper/90"} ${
                      isActive ? "animate-[riseIn_1000ms_var(--ease-out)_220ms_both]" : ""
                    }`}
                  >
                    {slide.body}
                  </p>
                  <Link
                    href={slide.ctaHref}
                    tabIndex={isActive ? 0 : -1}
                    className={`cta-secondary pointer-events-auto mt-8 ${isActive ? "animate-[riseIn_1000ms_var(--ease-out)_320ms_both]" : ""}`}
                  >
                    {slide.ctaLabel}
                  </Link>
                </div>
              </div>
            </div>
          </div>
        );
      })}

      {/* Chapters: the progress and the control in one. */}
      {count > 1 && (
        <div className="absolute inset-x-0 bottom-0 z-20">
          <div className="wrap-wide flex items-end gap-3 pb-7 md:gap-6">
            <ol className="grid flex-1 grid-cols-[repeat(auto-fit,minmax(0,1fr))] gap-3 md:gap-6">
              {slides.map((slide, index) => {
                const isActive = index === active;
                const done = index < active;
                return (
                  <li key={slide.id}>
                    <button
                      type="button"
                      onClick={() => go(index)}
                      aria-label={`Show slide ${index + 1}: ${slide.title}`}
                      aria-current={isActive ? "true" : undefined}
                      className={`group block w-full cursor-pointer pt-3 text-left ${slide.ink === "dark" && isActive ? "text-ink" : "text-paper"}`}
                    >
                      <span className="relative block h-px w-full overflow-hidden bg-current/30">
                        <span
                          key={isActive ? `run-${active}` : "idle"}
                          className="absolute inset-0 origin-left bg-gold-soft"
                          style={
                            isActive
                              ? running
                                ? { animation: `drawLine ${INTERVAL_MS}ms linear both` }
                                : { transform: "scaleX(1)" }
                              : { transform: done ? "scaleX(1)" : "scaleX(0)", opacity: done ? 0.5 : 1 }
                          }
                        />
                      </span>
                      <span className="mt-3 hidden items-baseline gap-2 font-ui text-[12px] tracking-[0.06em] opacity-70 transition-opacity group-hover:opacity-100 md:flex">
                        <span className="tabular-nums text-gold-soft">{String(index + 1).padStart(2, "0")}</span>
                        <span className={`truncate ${isActive ? "opacity-100" : ""}`}>{slide.title}</span>
                      </span>
                    </button>
                  </li>
                );
              })}
            </ol>
            <button
              type="button"
              onClick={() => setUserPaused((value) => !value)}
              className="inline-flex size-10 shrink-0 cursor-pointer items-center justify-center rounded-full border border-paper/40 text-paper backdrop-blur-sm transition-colors hover:border-paper hover:bg-paper/10"
              aria-label={userPaused ? "Play slideshow" : "Pause slideshow"}
            >
              {userPaused ? (
                <svg width="10" height="12" viewBox="0 0 10 12" fill="currentColor" aria-hidden="true">
                  <path d="M0 0l10 6-10 6z" />
                </svg>
              ) : (
                <svg width="10" height="12" viewBox="0 0 10 12" fill="currentColor" aria-hidden="true">
                  <rect width="3" height="12" />
                  <rect x="7" width="3" height="12" />
                </svg>
              )}
            </button>
          </div>
        </div>
      )}
    </section>
  );
}
