"use client";

import type { ArtPair } from "@/lib/content/sections";
import { StoryCarousel } from "./StoryCarousel";

interface StoreSlide {
  id: string;
  art: ArtPair;
  title: string;
  body: string;
  ctaLabel: string;
  ctaHref: string;
}

/**
 * The stores: each room's photograph full-bleed on the right, its name and an
 * invitation on the sand ground beside it, with the booking link as the
 * button.
 */
export function StoresSlideshow({ slides }: { slides: StoreSlide[] }) {
  return (
    <StoryCarousel
      slides={slides.map((slide) => ({ ...slide, eyebrow: "By appointment" }))}
      label="Our rooms"
      ground="sand"
      frame="full"
      imageSide="right"
    />
  );
}
