"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import Image from "next/image";
import Link from "next/link";

import { toneFor } from "../Frame";
import { ImageLink } from "../ImageLink";
import type { ArtPair } from "@/lib/content/sections";

export interface StorySlide {
  id: string;
  art: ArtPair;
  eyebrow?: string;
  title: string;
  body: string;
  ctaLabel: string;
  ctaHref: string;
}

const GROUND = {
  ivory: "bg-bg-alt text-ink",
  night: "booti-ground bg-night text-on-night",
  sand: "bg-bg-sand text-ink",
} as const;

/**
 * A story told in a few slides: the photograph on one side, the words on
 * their own ground on the other, never laid over the picture.
 *
 * Slides cross-dissolve; the photograph settles from slightly larger as it
 * arrives. A gold counter and two round arrows sit under the words. It
 * advances on its own every eight seconds, pauses on hover and focus, and
 * stands still for reduced-motion users.
 *
 * Three treatments share it, chosen by the band that uses it:
 *   ivory + arch   the editorial edits (womenswear, stoles)
 *   night + full   the campaigns
 *   sand  + full   the stores
 */
export function StoryCarousel({
  slides,
  label,
  ground,
  frame,
  imageSide,
}: {
  slides: StorySlide[];
  label: string;
  ground: keyof typeof GROUND;
  frame: "arch" | "full";
  imageSide: "left" | "right";
}) {
  const [active, setActive] = useState(0);
  const [paused, setPaused] = useState(false);
  const [reduced, setReduced] = useState(false);
  const rootRef = useRef<HTMLElement>(null);
  const count = slides.length;
  const night = ground === "night";

  useEffect(() => {
    const query = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReduced(query.matches);
  }, []);

  const go = useCallback((index: number) => setActive(((index % count) + count) % count), [count]);

  useEffect(() => {
    if (paused || reduced || count < 2) return;
    const timer = setTimeout(() => go(active + 1), 8000);
    return () => clearTimeout(timer);
  }, [paused, reduced, count, active, go]);

  if (count === 0) return null;

  const imageFirst = imageSide === "left";

  return (
    <section
      ref={rootRef}
      aria-label={label}
      aria-roledescription="carousel"
      className={`relative ${GROUND[ground]}`}
      onMouseEnter={() => setPaused(true)}
      onMouseLeave={() => setPaused(false)}
      onFocus={() => setPaused(true)}
      onBlur={(event) => {
        if (!rootRef.current?.contains(event.relatedTarget as Node)) setPaused(false);
      }}
    >
      <div
        className={`grid min-h-[min(88vh,860px)] ${
          imageFirst ? "md:grid-cols-[minmax(0,1.15fr)_minmax(0,1fr)]" : "md:grid-cols-[minmax(0,1fr)_minmax(0,1.15fr)]"
        }`}
      >
        {/* The photograph */}
        <div
          className={`relative min-h-[70vh] md:min-h-0 ${imageFirst ? "md:order-1" : "md:order-2"} ${
            frame === "arch" ? "flex items-center justify-center px-6 py-12 md:px-12 md:py-16" : ""
          }`}
        >
          <div
            className={
              frame === "arch"
                ? "frame-arch relative aspect-[3/4] h-auto w-full max-w-[520px] md:h-[min(74vh,720px)] md:w-auto"
                : "absolute inset-0 overflow-hidden"
            }
          >
            {slides.map((slide, index) => (
              <div
                key={slide.id}
                aria-hidden={index !== active}
                className={`absolute inset-0 transition-opacity duration-[1200ms] ease-[var(--ease-out)] ${
                  index === active ? "z-10 opacity-100" : "z-0 opacity-0"
                }`}
                style={{ backgroundColor: toneFor(slide.art.desktop.tone) }}
              >
                {slide.art.desktop.src ? (
                  <Image
                    src={slide.art.desktop.src}
                    alt={slide.title}
                    fill
                    sizes={frame === "arch" ? "(min-width: 768px) 540px, 100vw" : "(min-width: 768px) 55vw, 100vw"}
                    loading="lazy"
                    className={`object-cover object-center transition-transform duration-[2400ms] ease-[var(--ease-out)] ${
                      index === active ? "scale-100" : "scale-[1.06]"
                    }`}
                  />
                ) : null}
                {index === active && <ImageLink href={slide.ctaHref} duplicate className="absolute inset-0" />}
              </div>
            ))}
            {frame === "arch" && (
              <span aria-hidden="true" className="pointer-events-none absolute inset-2.5 z-20 rounded-[inherit] border border-paper/60" />
            )}
          </div>
        </div>

        {/* The words */}
        <div className={`flex items-center ${imageFirst ? "md:order-2" : "md:order-1"}`}>
          <div className="w-full px-6 py-16 md:px-[clamp(32px,6vw,112px)] md:py-20">
            <div className="relative min-h-[340px]">
              {slides.map((slide, index) => {
                const isActive = index === active;
                return (
                  <div
                    key={slide.id}
                    role="group"
                    aria-roledescription="slide"
                    aria-label={`${index + 1} of ${count}`}
                    aria-hidden={!isActive}
                    className={`transition-opacity duration-700 ${
                      isActive ? "relative opacity-100" : "pointer-events-none absolute inset-x-0 top-0 opacity-0"
                    }`}
                  >
                    {slide.eyebrow ? (
                      <p className={`eyebrow ${night ? "text-gold-soft" : ""} ${isActive ? "animate-[riseIn_800ms_var(--ease-out)_both]" : ""}`}>
                        {slide.eyebrow}
                      </p>
                    ) : null}
                    <h2
                      className={`mt-4 font-display text-[clamp(2.25rem,1.5rem+2.8vw,4rem)] leading-[1.02] ${
                        night ? "text-on-night" : "text-ink"
                      } ${isActive ? "animate-[riseIn_900ms_var(--ease-out)_80ms_both]" : ""}`}
                    >
                      {slide.title}
                    </h2>
                    <div className={`mt-6 h-px w-16 ${night ? "bg-gold-soft/60" : "bg-gold"}`} aria-hidden="true" />
                    <p
                      className={`mt-6 max-w-[46ch] font-serif text-[18px] leading-[1.65] md:text-[19px] ${
                        night ? "text-on-night-muted" : "text-ink-body"
                      } ${isActive ? "animate-[riseIn_900ms_var(--ease-out)_160ms_both]" : ""}`}
                    >
                      {slide.body}
                    </p>
                    <Link
                      href={slide.ctaHref}
                      tabIndex={isActive ? 0 : -1}
                      className={`${night ? "cta-secondary" : "cta-primary"} mt-9 ${isActive ? "animate-[riseIn_900ms_var(--ease-out)_240ms_both]" : ""}`}
                    >
                      {slide.ctaLabel}
                    </Link>
                  </div>
                );
              })}
            </div>

            {count > 1 && (
              <div className="mt-12 flex items-center gap-5">
                <p className={`font-ui text-[13px] tabular-nums tracking-[0.12em] ${night ? "text-gold-soft" : "text-accent"}`} aria-live="polite">
                  {String(active + 1).padStart(2, "0")}
                  <span className="mx-2 inline-block h-px w-8 translate-y-[-4px] bg-current opacity-50" aria-hidden="true" />
                  {String(count).padStart(2, "0")}
                </p>
                <div className="ml-auto flex gap-2">
                  {[
                    { label: "Previous", step: -1, d: "M9 1 2 7.5 9 14" },
                    { label: "Next", step: 1, d: "M2 1l7 6.5L2 14" },
                  ].map((arrow) => (
                    <button
                      key={arrow.label}
                      type="button"
                      onClick={() => go(active + arrow.step)}
                      aria-label={`${arrow.label} slide`}
                      className={`inline-flex size-12 cursor-pointer items-center justify-center rounded-full border transition-colors ${
                        night
                          ? "border-on-night/25 text-on-night hover:border-gold-soft hover:text-gold-soft"
                          : "border-ink/20 text-ink hover:border-ink hover:bg-ink hover:text-bg"
                      }`}
                    >
                      <svg width="11" height="15" viewBox="0 0 11 15" fill="none" stroke="currentColor" strokeWidth="1.3" aria-hidden="true">
                        <path d={arrow.d} />
                      </svg>
                    </button>
                  ))}
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </section>
  );
}
