"use client";

import type { ArtPair } from "@/lib/content/sections";
import { StoryCarousel } from "./StoryCarousel";

interface CampaignSlide {
  id: string;
  art: ArtPair;
  title: string;
  body: string;
  ctaLabel: string;
  ctaHref: string;
}

/**
 * The campaigns: the photograph full-bleed on the left, the story on the night
 * ground beside it, so a long paragraph never needs a scrim.
 */
export function CampaignSlideshow({ slides }: { slides: CampaignSlide[] }) {
  return (
    <StoryCarousel
      slides={slides.map((slide) => ({ ...slide, eyebrow: "Campaign" }))}
      label="Campaigns"
      ground="night"
      frame="full"
      imageSide="left"
    />
  );
}
